using App.Repositories;

namespace App;

/// <summary>What services depend on: a repository per table and a transaction. Each service operation runs in TransactionAsync: committed when it ends, rolled back when it fails.</summary>
public interface IUnitOfWork
{
    IThingRepository Things { get; }
    IKindRepository Kinds { get; }
    IOrderRepository OrderRows { get; }
    IEntryRepository Entries { get; }
    IEmptyRepository Empties { get; }

    /// <summary>Runs work with the repositories of the transaction; commits when it ends, rolls back when it throws.</summary>
    Task<T> TransactionAsync<T>(Func<IUnitOfWork, Task<T>> work);

    /// <summary>Runs work that returns nothing, in the same way.</summary>
    Task TransactionAsync(Func<IUnitOfWork, Task> work);
}

