using App.Common;
using App.Entities;

namespace App.Repositories;

/// <summary>Keeps empties rows in memory, for tests and for trying the services without a database.</summary>
public class MemoryEmptyRepository : IEmptyRepository
{
    private readonly Dictionary<string, Empty> rows = [];
    private long nextId = 1;

    /// <summary>The key of a row, as a list of its key values.</summary>
    private static object[] KeyOf(Empty row) => [row.Id];

    private static string KeyText(Empty row) => string.Join("|", KeyOf(row));

    /// <summary>Orders two keys value by value.</summary>
    private static int Compare(IReadOnlyList<object> a, IReadOnlyList<object> b)
    {
        for (var index = 0; index < a.Count; index++)
        {
            var order = Comparer<object>.Default.Compare(a[index], b[index]);
            if (order != 0) return order;
        }
        return 0;
    }

    private IEnumerable<Empty> Visible() =>
        rows.Values.Where(row => true).OrderBy(KeyOf, Comparer<object[]>.Create((a, b) => Compare(a, b)));

    public Task<Empty?> FindByIdAsync(long id)
    {
        return Task.FromResult(Visible().FirstOrDefault(row => Equals(row.Id, id)));
    }

    public Task<Page<Empty>> ListAsync(int offset, int limit)
    {
        var rows = Visible().ToList();
        return Task.FromResult(new Page<Empty>(rows.Skip(offset).Take(limit).ToList(), rows.Count, offset, limit));
    }

    public Task<Empty> InsertAsync(Empty entity)
    {
        if (entity.Id == 0) entity.Id = nextId++;
        rows[KeyText(entity)] = entity;
        return Task.FromResult(entity);
    }

    public Task<Empty> UpdateAsync(Empty entity)
    {
        rows[KeyText(entity)] = entity;
        return Task.FromResult(entity);
    }

    public Task DeleteAsync(Empty entity)
    {
        rows.Remove(KeyText(entity));
        return Task.CompletedTask;
    }
}

