/// <summary>Keeps things rows in memory, for tests and for trying the services without a database.</summary>
public class MemoryThingRepository : IThingRepository
{
    private readonly Dictionary<string, Thing> rows = [];

    /// <summary>The key of a row, as a list of its key values.</summary>
    private static object[] KeyOf(Thing row) => [row.Id];

    private static string KeyText(Thing row) => string.Join("|", KeyOf(row));

    /// <summary>Orders two keys value by value.</summary>
    private static int Compare(IReadOnlyList<object> a, IReadOnlyList<object> b)
    {
        for (var index = 0; index < a.Count; index++)
        {
            var order = Comparer<object>.Default.Compare(a[index], b[index]);
            if (order != 0) return order;
        }
        return 0;
    }

    private IEnumerable<Thing> Visible() =>
        rows.Values.Where(row => true).OrderBy(KeyOf, Comparer<object[]>.Create((a, b) => Compare(a, b)));

    public Task<Thing?> FindByIdAsync(Guid id)
    {
        return Task.FromResult(Visible().FirstOrDefault(row => Equals(row.Id, id)));
    }

    public Task<Page<Thing>> ListAsync(int offset, int limit)
    {
        var rows = Visible().ToList();
        return Task.FromResult(new Page<Thing>(rows.Skip(offset).Take(limit).ToList(), rows.Count, offset, limit));
    }

    public Task<Thing> InsertAsync(Thing entity)
    {
        if (entity.Id == Guid.Empty) entity.Id = Guid.NewGuid();
        entity.Flag ??= true;
        entity.Changed ??= DateTimeOffset.UtcNow;
        rows[KeyText(entity)] = entity;
        return Task.FromResult(entity);
    }

    public Task<Thing> UpdateAsync(Thing entity)
    {
        rows[KeyText(entity)] = entity;
        return Task.FromResult(entity);
    }

    public Task DeleteAsync(Thing entity)
    {
        rows.Remove(KeyText(entity));
        return Task.CompletedTask;
    }
}

