using App;
using App.Common;
using App.Entities;
using App.Errors;

namespace App.Services;

/// <summary>Operations on things. Each write runs in its own transaction.</summary>
public class ThingService(IUnitOfWork unitOfWork)
{
    // TODO: token is returned with the entity; use DTOs to leave it out
    private readonly IUnitOfWork uow = unitOfWork;

    /// <summary>Checks the values against the rules of the "things" table, and the rows they point to; throws ValidationFailedException with every problem.</summary>
    private static async Task ValidateAsync(IUnitOfWork uow, Dictionary<string, object?> values, Thing? current)
    {
        var creating = current is null;
        var errors = new List<FieldError>();
        {
            var value = values.GetValueOrDefault("Token");
            if (value is null)
                if (creating || values.ContainsKey("Token")) errors.Add(new FieldError("token", "is required"));
        }
        {
            var value = values.GetValueOrDefault("Small");
            if (value is null)
                if (creating || values.ContainsKey("Small")) errors.Add(new FieldError("small", "is required"));
        }
        {
            var value = values.GetValueOrDefault("Big");
            if (value is null)
                if (creating || values.ContainsKey("Big")) errors.Add(new FieldError("big", "is required"));
        }
        {
            var value = values.GetValueOrDefault("Price");
            if (value is null)
                if (creating || values.ContainsKey("Price")) errors.Add(new FieldError("price", "is required"));
        }
        {
            var value = values.GetValueOrDefault("R");
            if (value is null)
                if (creating || values.ContainsKey("R")) errors.Add(new FieldError("r", "is required"));
        }
        {
            var value = values.GetValueOrDefault("Flag");
            if (value is null)
                if (!creating && values.ContainsKey("Flag")) errors.Add(new FieldError("flag", "cannot be empty"));
        }
        {
            var value = values.GetValueOrDefault("Born");
            if (value is null)
                if (creating || values.ContainsKey("Born")) errors.Add(new FieldError("born", "is required"));
        }
        {
            var value = values.GetValueOrDefault("Opens");
            if (value is null)
                if (creating || values.ContainsKey("Opens")) errors.Add(new FieldError("opens", "is required"));
        }
        {
            var value = values.GetValueOrDefault("OpensTz");
            if (value is null)
                if (creating || values.ContainsKey("OpensTz")) errors.Add(new FieldError("opens_tz", "is required"));
        }
        {
            var value = values.GetValueOrDefault("At");
            if (value is null)
                if (creating || values.ContainsKey("At")) errors.Add(new FieldError("at", "is required"));
        }
        {
            var value = values.GetValueOrDefault("AtTz");
            if (value is null)
                if (creating || values.ContainsKey("AtTz")) errors.Add(new FieldError("at_tz", "is required"));
        }
        {
            var value = values.GetValueOrDefault("Bin");
            if (value is null)
                if (creating || values.ContainsKey("Bin")) errors.Add(new FieldError("bin", "is required"));
        }
        {
            var value = values.GetValueOrDefault("Data");
            if (value is null)
                if (creating || values.ContainsKey("Data")) errors.Add(new FieldError("data", "is required"));
        }
        {
            var value = values.GetValueOrDefault("Feeling");
            if (value is null)
                if (creating || values.ContainsKey("Feeling")) errors.Add(new FieldError("feeling", "is required"));
        }
        {
            var value = values.GetValueOrDefault("Tags");
            if (value is null)
                if (creating || values.ContainsKey("Tags")) errors.Add(new FieldError("tags", "is required"));
        }
        {
            var value = values.GetValueOrDefault("Code");
            if (value is null)
            {
                if (creating || values.ContainsKey("Code")) errors.Add(new FieldError("code", "is required"));
            }
            else
            {
                if (value is string text && text.Length > 5) errors.Add(new FieldError("code", "is longer than 5 characters"));
            }
        }
        if (errors.Count > 0) throw new ValidationFailedException("Thing", errors);
    }

    /// <summary>Every check before a write: the values, the rows they point to, the unique values.</summary>
    private static async Task CheckAsync(IUnitOfWork uow, Dictionary<string, object?> values, Thing? current)
    {
        await ValidateAsync(uow, values, current);
    }

    /// <summary>Sets the given values on the entity.</summary>
    private static void Apply(Thing entity, Dictionary<string, object?> values)
    {
        if (values.TryGetValue("Token", out var token)) entity.Token = (Guid)token!;
        if (values.TryGetValue("Small", out var small)) entity.Small = (short)small!;
        if (values.TryGetValue("Num", out var num)) entity.Num = (int?)num;
        if (values.TryGetValue("Big", out var big)) entity.Big = (long)big!;
        if (values.TryGetValue("Price", out var price)) entity.Price = (decimal)price!;
        if (values.TryGetValue("R", out var r)) entity.R = (float)r!;
        if (values.TryGetValue("D", out var d)) entity.D = (double?)d;
        if (values.TryGetValue("Flag", out var flag)) entity.Flag = (bool?)flag;
        if (values.TryGetValue("Born", out var born)) entity.Born = (DateOnly)born!;
        if (values.TryGetValue("Opens", out var opens)) entity.Opens = (TimeOnly)opens!;
        if (values.TryGetValue("OpensTz", out var opensTz)) entity.OpensTz = (DateTimeOffset)opensTz!;
        if (values.TryGetValue("At", out var at)) entity.At = (DateTime)at!;
        if (values.TryGetValue("AtTz", out var atTz)) entity.AtTz = (DateTimeOffset)atTz!;
        if (values.TryGetValue("Bin", out var bin)) entity.Bin = (byte[])bin!;
        if (values.TryGetValue("Data", out var dataValue)) entity.Data = (string)dataValue!;
        if (values.TryGetValue("Plain", out var plain)) entity.Plain = (string?)plain;
        if (values.TryGetValue("Feeling", out var feeling)) entity.Feeling = (string)feeling!;
        if (values.TryGetValue("Tags", out var tags)) entity.Tags = (string)tags!;
        if (values.TryGetValue("Numbers", out var numbers)) entity.Numbers = (string?)numbers;
        if (values.TryGetValue("Ip", out var ip)) entity.Ip = (string?)ip;
        if (values.TryGetValue("Span", out var span)) entity.Span = (string?)span;
        if (values.TryGetValue("Code", out var code)) entity.Code = (string)code!;
        if (values.TryGetValue("Note", out var note)) entity.Note = (string?)note;
    }

    /// <summary>The Thing with this key; NotFoundException when there is none.</summary>
    private static async Task<Thing> FindAsync(IUnitOfWork uow, Guid id) =>
        await uow.Things.FindByIdAsync(id) ?? throw new NotFoundException("Thing", id);

    /// <summary>The values an update gives, by field.</summary>
    private static Dictionary<string, object?> Given(ThingChanges changes)
    {
        var values = new Dictionary<string, object?>();
        if (changes.Token is { IsPresent: true } token) values["Token"] = token.Value;
        if (changes.Small is { IsPresent: true } small) values["Small"] = small.Value;
        if (changes.Num is { IsPresent: true } num) values["Num"] = num.Value;
        if (changes.Big is { IsPresent: true } big) values["Big"] = big.Value;
        if (changes.Price is { IsPresent: true } price) values["Price"] = price.Value;
        if (changes.R is { IsPresent: true } r) values["R"] = r.Value;
        if (changes.D is { IsPresent: true } d) values["D"] = d.Value;
        if (changes.Flag is { IsPresent: true } flag) values["Flag"] = flag.Value;
        if (changes.Born is { IsPresent: true } born) values["Born"] = born.Value;
        if (changes.Opens is { IsPresent: true } opens) values["Opens"] = opens.Value;
        if (changes.OpensTz is { IsPresent: true } opensTz) values["OpensTz"] = opensTz.Value;
        if (changes.At is { IsPresent: true } at) values["At"] = at.Value;
        if (changes.AtTz is { IsPresent: true } atTz) values["AtTz"] = atTz.Value;
        if (changes.Bin is { IsPresent: true } bin) values["Bin"] = bin.Value;
        if (changes.Data is { IsPresent: true } dataValue) values["Data"] = dataValue.Value;
        if (changes.Plain is { IsPresent: true } plain) values["Plain"] = plain.Value;
        if (changes.Feeling is { IsPresent: true } feeling) values["Feeling"] = feeling.Value;
        if (changes.Tags is { IsPresent: true } tags) values["Tags"] = tags.Value;
        if (changes.Numbers is { IsPresent: true } numbers) values["Numbers"] = numbers.Value;
        if (changes.Ip is { IsPresent: true } ip) values["Ip"] = ip.Value;
        if (changes.Span is { IsPresent: true } span) values["Span"] = span.Value;
        if (changes.Code is { IsPresent: true } code) values["Code"] = code.Value;
        if (changes.Note is { IsPresent: true } note) values["Note"] = note.Value;
        return values;
    }

    /// <summary>Stores a new Thing after checking it.</summary>
    public async Task<Thing> CreateThingAsync(Thing thing)
    {
        var values = new Dictionary<string, object?>();
        values["Token"] = thing.Token;
        values["Small"] = thing.Small;
        if (thing.Num is not null) values["Num"] = thing.Num;
        values["Big"] = thing.Big;
        values["Price"] = thing.Price;
        values["R"] = thing.R;
        if (thing.D is not null) values["D"] = thing.D;
        if (thing.Flag is not null) values["Flag"] = thing.Flag;
        values["Born"] = thing.Born;
        values["Opens"] = thing.Opens;
        values["OpensTz"] = thing.OpensTz;
        values["At"] = thing.At;
        values["AtTz"] = thing.AtTz;
        if (thing.Bin is not null) values["Bin"] = thing.Bin;
        if (thing.Data is not null) values["Data"] = thing.Data;
        if (thing.Plain is not null) values["Plain"] = thing.Plain;
        if (thing.Feeling is not null) values["Feeling"] = thing.Feeling;
        if (thing.Tags is not null) values["Tags"] = thing.Tags;
        if (thing.Numbers is not null) values["Numbers"] = thing.Numbers;
        if (thing.Ip is not null) values["Ip"] = thing.Ip;
        if (thing.Span is not null) values["Span"] = thing.Span;
        if (thing.Code is not null) values["Code"] = thing.Code;
        if (thing.Note is not null) values["Note"] = thing.Note;
        return await this.uow.TransactionAsync(async uow =>
        {
            await CheckAsync(uow, values, null);
            return await uow.Things.InsertAsync(thing);
        });
    }

    /// <summary>The Thing with this key; NotFoundException when there is none.</summary>
    public async Task<Thing> GetThingAsync(Guid id) => await FindAsync(uow, id);

    /// <summary>A page of things, by primary key.</summary>
    public async Task<Page<Thing>> ListThingsAsync(int offset, int limit) => await uow.Things.ListAsync(offset, limit);

    /// <summary>Changes the given values of a Thing.</summary>
    public async Task<Thing> UpdateThingAsync(Guid id, ThingChanges changes)
    {
        var values = Given(changes);
        return await this.uow.TransactionAsync(async uow =>
        {
            var current = await FindAsync(uow, id);
            await CheckAsync(uow, values, current);
            Apply(current, values);
            return await uow.Things.UpdateAsync(current);
        });
    }

    /// <summary>Deletes a Thing.</summary>
    public async Task DeleteThingAsync(Guid id)
    {
        await this.uow.TransactionAsync(async uow =>
        {
            var current = await FindAsync(uow, id);
            await uow.Things.DeleteAsync(current);
        });
    }
}

